"""Original chest examination questions: integrate physical signs rather than single labels."""
from qbank_authoring import question,ref
rows=[]
CH=ref('Clinical Methods: chest examination','https://www.ncbi.nlm.nih.gov/books/NBK368/')
OV=ref('Clinical Methods: overview of pulmonary examination','https://www.ncbi.nlm.nih.gov/books/NBK356/')
GI=ref('GINA asthma strategy: 2026','https://ginasthma.org/wp-content/uploads/2026/05/GINA-2026-Strategy-Report-WMS.pdf')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A febrile patient has focal dullness, increased tactile vocal fremitus and bronchial breathing. Which process best fits?', 'Air-space consolidation with a patent conducting airway',[
 ('A large pleural effusion over the same area','Pleural fluid generally reduces fremitus and breath-sound transmission over the fluid.'),('An uncomplicated pneumothorax','This more often produces hyperresonance and reduced transmission.'),('Diffuse emphysema alone','This does not explain focal dullness with enhanced voice transmission.')],
 'Density and airway patency jointly determine sound transmission','**Consolidated lung can transmit central airway sounds unusually well.**',['The conducting airway must remain patent for the classic pattern.','Examination suggests a process rather than establishing a microbiological cause.'],'**Confirm extent and cause with appropriate imaging and investigation.**',['Compare symmetrical sites.','Assess oxygenation and systemic severity.'],[['Consolidation','Dull + increased transmission'],['Effusion','Dull + reduced transmission'],['Pneumothorax','Hyperresonant + reduced transmission']],[CH],style='clinical_scenario')

q('Stony dullness with reduced breath sounds and reduced vocal fremitus at one base most strongly suggests which process?', 'Pleural effusion',[
 ('Patent-airway lobar consolidation','This more often increases vocal transmission.'),('Pneumothorax','This more often produces hyperresonance.'),('Isolated bronchospasm','This usually produces a different diffuse airway pattern.')],
 'A fluid layer changes both percussion and sound conduction','**Pleural fluid separates the chest wall from ventilated lung.**',['Signs depend on volume and patient position.','Ultrasound detects and characterizes fluid more accurately than examination alone.'],'**Use imaging before planning aspiration or drainage.**',['Determine cause and urgency.','Do not infer transudate versus exudate from stony dullness alone.'],[['Percussion','Markedly dull'],['Transmission','Reduced over fluid'],['Confirmation','Ultrasound/imaging']],[CH,OV])

q('Sudden unilateral chest pain is accompanied by hyperresonance, reduced expansion and markedly reduced breath sounds. Which diagnosis is most likely?', 'Pneumothorax',[
 ('Pleural effusion','Its percussion note is generally dull rather than hyperresonant.'),('Lobar consolidation','It commonly increases rather than markedly reduces vocal transmission when the airway is patent.'),('Pulmonary fibrosis','This is usually a different chronic restrictive examination pattern.')],
 'Pleural air impairs mechanical expansion and sound transmission','**The sign combination supports a pleural-air process.**',['Examination sensitivity varies with size and body habitus.','Assess immediately for hemodynamic compromise and tension physiology.'],'**Use urgent appropriate confirmation/treatment according to stability.**',['Do not delay decompression for imaging when tension is strongly suspected in an unstable patient.','Consider other causes of unilateral quietness if the pattern is incomplete.'],[['Percussion','Hyperresonance'],['Breathing','Reduced on affected side'],['Urgency','Depends on stability/tension']],[CH],style='clinical_scenario')

q('A hemithorax is dull and quiet, with reduced volume and the trachea pulled toward that side. Which process is favored?', 'Major atelectatic volume loss',[
 ('A large space-occupying pleural effusion','This more often shifts the mediastinum away, although mixed disease can alter the pattern.'),('Tension pneumothorax','This generally produces pressure-related contralateral shift and hyperresonance.'),('Simple diffuse bronchospasm','This does not explain focal volume loss and traction.')],
 'Distinguish loss of volume from added volume','**Collapse can pull the mediastinum toward the affected side.**',['Pleural fluid or air under pressure can push away.','Obstruction, surgery and other causes need consideration.'],'**Use imaging to identify the cause and any mixed process.**',['Assess for an obstructing lesion or mucus plug when appropriate.','Do not use tracheal position alone as a complete diagnosis.'],[['Volume loss','Pull toward'],['Space/pressure gain','Push away'],['Mixed disease','May balance or alter shift']],[CH],style='clinical_scenario')

q('Why may bronchial breathing be absent over a collapsed lobe with a completely obstructed bronchus?', 'The blocked airway prevents effective transmission of central respiratory sound to that region',[
 ('Every dense lung region must always transmit loud bronchial sounds','Airway patency is also important.'),('Collapse necessarily increases aeration','It reduces lung volume and aeration.'),('Auscultation becomes a direct measure of pulmonary artery pressure','It does not quantify vascular pressure.')],
 'Density alone is not enough to predict the sound','**A patent sound-conducting route is required for the classic consolidation pattern.**',['Obstruction can produce a quiet dense region.','Compression and partial patency can create other patterns.'],'**Integrate volume, percussion and imaging.**',['Do not exclude collapse because no bronchial breathing is heard.','Investigate the obstruction when clinically indicated.'],[['Dense tissue','Potential sound conduit'],['Blocked bronchus','Transmission interrupted'],['Diagnosis','Combined findings']],[CH])

q('A patient’s spoken “E” is heard as a nasal “A” through the stethoscope over a focal lung area. What is this sign?', 'Egophony',[
 ('A pleural friction rub','This is a grating respiratory sound rather than altered voice transmission.'),('Stridor','This is a high-pitched airway sound.'),('Succussion splash','This is a different fluid/air-related physical sign.')],
 'Voice testing probes transmission through the thorax','**Egophony is an altered quality of transmitted vocal sound.**',['It can occur with consolidation or near the upper margin of an effusion.','Localization and the rest of the examination determine interpretation.'],'**Correlate with percussion, breath sounds and imaging.**',['Do not equate the sign with one pathogen.','Compare with a normal region using consistent technique.'],[['Test','Spoken vowel'],['Finding','E-to-A quality change'],['Context','Consolidation/effusion edge']],[CH,OV])

q('A loud high-pitched predominantly inspiratory sound is heard best over the neck. Which process should be suspected?', 'Upper or central airway narrowing producing stridor',[
 ('Diffuse small-airway wheeze as the most likely source','That is usually more prominent over the chest and often expiratory.'),('Fine basal interstitial crackles','These are discontinuous inspiratory sounds, not a neck-centered musical sound.'),('A pleural rub as the usual mechanism','A rub is localized grating from pleural movement.')],
 'Sound location and respiratory phase guide localization','**Stridor can indicate a threatened airway.**',['Phase can vary with the level and nature of obstruction.','Voice change, retraction and fatigue increase concern.'],'**Assess airway stability urgently.**',['Avoid distressing an unstable patient with unnecessary examination.','Obtain appropriate expert airway evaluation.'],[['Source','Upper/central airway'],['Sound','High pitched'],['Priority','Airway safety']],[CH],style='clinical_scenario')

q('A persistent localized monophonic wheeze is heard over one lung region. Which next inference is most appropriate?', 'Consider focal large-airway obstruction rather than assuming diffuse asthma',[
 ('It proves all airways are diffusely narrowed','A localized single-tone sound suggests a focal process.'),('It excludes an endobronchial lesion','A lesion is an important possible cause.'),('It is diagnostic of pleural effusion','The typical effusion pattern is different.')],
 'A sound can localize an obstructed airway','**A focal wheeze can arise from a narrowed bronchus.**',['Foreign body, tumor or other localized obstruction may be responsible.','Asthma can coexist but should not absorb a discordant sign.'],'**Investigate according to history, imaging and persistence.**',['Assess sudden onset and aspiration risk.','Consider bronchoscopy when indicated.'],[['Diffuse polyphonic','Widespread airway narrowing'],['Localized monophonic','Focal obstruction clue'],['Action','Cause-directed evaluation']],[CH],style='clinical_scenario')

q('An exhausted patient with severe asthma has very little audible wheeze and minimal air entry. What is the safest interpretation?', 'A quiet chest may reflect critically reduced airflow rather than improvement',[
 ('Less wheeze always proves bronchodilator success','Sound requires airflow; severe obstruction can become quiet.'),('Asthma is excluded when wheeze is absent','The absence of wheeze does not exclude a severe exacerbation.'),('Auscultation alone establishes normal ventilation','Ventilation and effort require broader assessment.')],
 'Less sound can mean less flow','**A silent or nearly silent chest is a severe warning sign in the right context.**',['Assess speech, respiratory effort, consciousness, oxygenation and objective flow when feasible.','Do not delay emergency support to complete nonessential testing.'],'**Treat as a potentially life-threatening exacerbation.**',['Escalate experienced care and monitor for fatigue.','A normal or rising CO2 in a severely distressed patient can be concerning.'],[['Wheeze','Flow-dependent sound'],['Quiet chest','Possible critical obstruction'],['Assessment','Whole severity picture']],[GI],style='clinical_scenario')

q('Fine late-inspiratory basal crackles with clubbing and a restrictive clinical pattern most strongly suggest which process?', 'Fibrotic interstitial lung disease',[
 ('Uncomplicated chronic bronchitis alone','The fine late crackles/clubbing pattern suggests an additional interstitial process.'),('A large isolated pneumothorax','This more often causes reduced breath sounds and hyperresonance.'),('A purely upper-airway lesion','This does not explain the basal parenchymal findings.')],
 'Crackle timing and associated signs narrow the differential','**Reopening of small airways/units in abnormal interstitial lung can generate fine inspiratory sounds.**',['Pulmonary edema and other processes can also cause crackles.','The examination is not specific for a particular ILD subtype.'],'**Use imaging, physiology and exposure/systemic history.**',['Look for autoimmune, occupational and medication clues.','Do not diagnose IPF from crackles alone.'],[['Crackles','Fine/late inspiratory'],['Context','Clubbing/restrictive pattern'],['Next step','ILD evaluation']],[CH],style='clinical_scenario')

q('Coarse crackles and rhonchi change after coughing in a patient with chronic copious sputum. Which mechanism is supported?', 'Airway secretions and larger-airway disease',[
 ('A fixed pleural rub as the only explanation','A rub usually does not clear or substantially change with coughing.'),('Pure fibrotic crackles as established by any crackle','Secretory changes after cough suggest an airway component.'),('A normal chest examination','Persistent coarse sounds with symptoms require assessment.')],
 'Response to cough provides mechanistic information','**Movable secretions can alter airway sounds.**',['Bronchiectasis is one possible cause in the appropriate history.','Coexisting parenchymal disease can add other sounds.'],'**Investigate chronic productive symptoms appropriately.**',['Review recurrent infections, sputum and imaging.','Do not identify a bacterial species from the sound.'],[['Cough response','Supports secretion component'],['Airway disease','Possible bronchiectasis and others'],['Limit','Not etiological confirmation']],[CH],style='clinical_scenario')

q('A localized grating chest sound stops when breathing is held. Which source is favored?', 'Pleural friction rub',[
 ('A pericardial rub that must stop whenever respiration stops','A cardiac-related rub can persist during breath holding.'),('A fixed valvular murmur','This follows cardiac rather than respiratory movement.'),('An arterial bruit','This is a vascular flow sound.')],
 'Temporarily remove respiratory movement to clarify the source','**Inflamed pleural surfaces can rub during inspiration and expiration.**',['A pleural rub can accompany several causes of pleurisy.','Hair or stethoscope movement can create artifacts.'],'**Correlate with pain, respiratory phase and other findings.**',['Do not repeatedly force breath holding in a distressed patient.','Investigate the cause rather than treating the rub as a diagnosis.'],[['Pleural','Respiratory movement dependent'],['Pericardial','Cardiac-cycle relationship'],['Artifact','Exclude skin/hair movement']],[OV])
